import React, { useState } from 'react'
import {useHistory} from 'react-router-dom';

const Login = () => {
    let history = useHistory();
    const [credentials,setcredentials] = useState({email:"",password:""});
    const handlesubmit = async(e)=>{
        e.preventDefault();
        const response = await fetch("http://localhost:5001/api/auth/login", {
               method: "POST",
               headers: {
                   "Content-Type": "application/json",
               },
               body: JSON.stringify({ email:credentials.email,password:credentials.password }),
           });
           const json = await response.json();
           console.log(json);
           if(json.success) {
            //Save the token and redirect
            localStorage.setItem("token",json.authtoken);

           } else {
            alert("Wrong credentials")
           }
    }
    const onChange=(e)=>{
        setcredentials({...credentials,[e.target.name]:e.target.value});
    }
    return (
        <div>
            <form onSubmit={handlesubmit}>
                <div className="mb-3">
                    <label htmlFor="email" className="form-label">Email address</label>
                    <input type="email" className="form-control" onChange={onChange} id="email" name="email" aria-describedby="emailHelp" value={credentials.email} style={{width:"500px"}}/>
                </div>
                <div className="mb-3">
                    <label htmlFor="password" className="form-label">Password</label>
                    <input type="password" className="form-control" onChange={onChange} id="password" name="password" value={credentials.password} style={{width:"500px"}}/>
                </div>
                <button type="submit"  className="btn btn-info">Submit</button>
            </form>
        </div>
    )
}

export default Login
